using System.Text.Json;
using A33.Instrument.Core;
namespace A33.Instrument.HardwareValidation;
public static class ApplyRestoreRunner
{
 public static async Task<int> RunAsync(string[] args){if(!args.Contains("--allow-ram-write")||Get(args,"confirmation","")!="APPLY_RAM_ONLY"){Console.Error.WriteLine("RAM_WRITE_AUTHORIZATION_REQUIRED");return 3;}var output=Get(args,"output","Results/pc_stage2b_hw/tcp_apply_restore_summary.json");var result=new Dictionary<string,object?>{{"command","apply-restore-test"},{"clientCommit","a46ccf9"},{"firmwareCommit","71a6124"},{"tokenPlan","6,7,8,9,10,11"},{"saveRequests",0},{"cancelRequests",0}};try{await using var m=new InstrumentMonitoringService();await m.ConnectAsync(new MonitoringOptions(TransportMode.Tcp,"192.168.1.100",502,"",115200,1,3000,1000,200));await m.StartMonitoringAsync();await Task.Delay(1000);var c=new ConfigurationTransactionService(m,6);var s=await c.RefreshAsync();var original=s.Active.ToArray();c.Edit("brightness",4);await c.ValidateAsync();await c.ApplyRamAsync(false);var applied=await c.RefreshAsync();result["appliedBrightness"]=applied.Fields.Single(f=>f.Key=="brightness").Current[0];await Task.Delay(TimeSpan.FromSeconds(int.Parse(Get(args,"observe-seconds","10"))));c.Edit("brightness",3);await c.ValidateAsync();await c.ApplyRamAsync(false);var restored=await c.RefreshAsync();result["restoredBrightness"]=restored.Fields.Single(f=>f.Key=="brightness").Current[0];result["activeUnchangedExceptBrightness"]=original.Select((v,i)=>(v,i)).Where(x=>x.i!=22).All(x=>x.v==restored.Active[x.i]);result["status"]="PASS";await m.StopMonitoringAsync();await m.DisconnectAsync();}catch(Exception e){result["status"]="FAIL";result["error"]=e.Message;return await Write(result,output,6);}return await Write(result,output,0);}
 private static string Get(string[] a,string k,string f){for(var i=0;i<a.Length-1;i++)if(a[i].Equals("--"+k,StringComparison.OrdinalIgnoreCase))return a[i+1];return f;}private static async Task<int> Write(Dictionary<string,object?>r,string p,int code){var j=JsonSerializer.Serialize(r,new JsonSerializerOptions{WriteIndented=true});Console.WriteLine(j);await File.WriteAllTextAsync(p,j);return code;}
}
